export function balancedBrackets(text: string): boolean {
  const stack: string[] = [];
  const opening = new Map([[')', '('], [']', '['], ['}', '{']]);
  for (const char of text) {
    if (opening.has(char)) {
      if (stack.pop() !== opening.get(char)) return false;
    } else stack.push(char);
  }
  return stack.length === 0;
}
